const body = $input.first().json.body ?? $input.first().json;
const ev = body.events?.[0];
if (!ev) return [{ json: { isVerify: true } }];
const text = (ev.message?.text ?? '').trim();
return [{ json: {
  isVerify: false,
  userId: ev.source?.userId ?? '',
  replyToken: ev.replyToken ?? '',
  text,
  prompt: text
}}];

const j = $input.first().json;
const text = (j.prompt ?? '').trim();
const s = $getWorkflowStaticData('global');
const p = s.pending;
let cmd = 'new';
if (!text) cmd = 'fallback';
else if (p) {
  if (/^(好|好的|確認|確定|執行|可以|要|沒問題|yes|ok|okay|做吧|開始吧|動手吧)[。！!，,\s]*$/i.test(text)) cmd = 'confirm';
  else if (text.length < 8 && /^(好|確認|執行|yes|ok)/i.test(text)) cmd = 'confirm';
  else if (/取消|不要了|算了|不用了|別做|停止|cancel/i.test(text)) cmd = 'fallback';
  else cmd = 'new';
} else {
  if (/^(status|狀態|在嗎|還在嗎|健康檢查|上線嗎|test)/i.test(text) || (/狀態/.test(text) && text.length < 12)) cmd = 'status';
  else if (/取消|說明|幫助|help|用法|指令/i.test(text) && text.length < 12) cmd = 'fallback';
  else cmd = 'new';
}
return [{ json: { ...j, cmd } }];

const j = $input.first().json;
const s = $getWorkflowStaticData('global');
const p = s.pending;
const pend = p ? `待確認: ${p.prompt?.slice(0,200)} (${Math.round((Date.now()-p.createdAt)/1000)}秒前)，回 好 執行、取消 取消` : '無待確認事項';
const online = (j && j.healthy === true) ? ('正常' + (j.version ? ` (v${j.version})` : '')) : '離線或無回應';
let uid = '';
try { uid = $('Parse LINE').first().json.userId ?? ''; } catch(e) {}
return [{ json: { userId: uid, output: `桌機 opencode: ${online}\n工作目錄: C:\\Users\\ryan\\Desktop\\opencode\n${pend}\n直接傳訊息即可，問答直接回，改程式會先預覽` } }];

const j = $input.first().json;
const p = (j.prompt ?? '').trim();
const DIR = 'C:\\Users\\ryan\\Desktop\\opencode';
if (!p) return [{ json: { ...j, blocked: true, output: '空指令，已忽略。用法: /run 把按鈕改成藍色' } }];
const bad = [/rm\s+-rf\s+[\/~.]/i, /remove-item\b.*(-recurse|\/s)/i, /\bdel\s+\/[sfq]/i, /\bformat\s+[a-z]:/i, /\b(rd|rmdir)\s+\/s/i, /\.env/i, /NGROK_AUTHTOKEN/i, /CHANNEL_ACCESS_TOKEN/i, /OPENCODE_SERVER_PASSWORD/i, /\.git[\/\\]/i, /\bgit\s+push\b/i, /\bgit\s+reset\s+--hard\b/i, /\bnpm\s+publish\b/i, /\b(shutdown|taskkill|stop-process|stop-computer)\b/i, /\breg\s+delete\b/i, /\b(ssh|scp|plink)\b/i, /\|\s*(ba|z)?sh\b/i, /\b(invoke-webrequest|invoke-restmethod|iwr|curl)\b/i, /base64\s+-d/i];
const hit = bad.find(r => r.test(p));
if (hit) return [{ json: { ...j, blocked: true, output: '已擋下高風險字 (' + hit + ')，請換說法或本機處理。' } }];
return [{ json: { ...j, blocked: false, directory: DIR, output: '' } }];

const j = $input.first().json;
const s = $getWorkflowStaticData('global');
s.pending = { userId: j.userId, prompt: j.prompt, directory: j.directory, createdAt: Date.now() };
return [{ json: { userId: j.userId, output: `要執行(未執行):\n${j.prompt.slice(0,1000)}\n目錄: ${j.directory}\n請 5 分鐘內回 好 執行，取消 取消` } }];

const j = $input.first().json;
const s = $getWorkflowStaticData('global');
const p = s.pending;
if (!p) return [{ json: { userId: j.userId, valid: false, output: '沒有待確認事項，直接傳訊息即可。' } }];
if (p.userId !== j.userId) return [{ json: { userId: j.userId, valid: false, output: '那筆待確認不是你的，已忽略。' } }];
if (Date.now() - p.createdAt > 5*60*1000) { delete s.pending; return [{ json: { userId: j.userId, valid: false, output: '已超過5分鐘，請重傳一次需求。' } }]; }
delete s.pending;
return [{ json: { userId: j.userId, valid: true, prompt: p.prompt, directory: p.directory, output: '' } }];

const first = $input.first().json;
let uid = '';
try { uid = $('Parse LINE').first().json.userId ?? ''; } catch(e) {}
const parts = first.parts ?? [];
let txt = '';
if (Array.isArray(parts)) { txt = parts.filter(p => p && p.type === 'text' && p.text).map(p => p.text).join('\n'); }
if (!txt) { txt = (first.output ?? first.text ?? JSON.stringify(first)).toString(); }
txt = txt.slice(0, 4800) || '執行完成';
return [{ json: { userId: uid, output: `執行完成:\n${txt}` } }];

const first = $input.first().json;
let orig = '';
let uid = '';
try { orig = $('Detect intent').first().json.prompt ?? ''; } catch(e) {}
try { uid = $('Detect intent').first().json.userId ?? ''; } catch(e) {}
if (!uid) { try { uid = $('Parse LINE').first().json.userId ?? ''; } catch(e) {} }
const parts = first.parts ?? [];
let txt = '';
if (Array.isArray(parts)) { txt = parts.filter(p => p && p.type === 'text' && p.text).map(p => p.text).join('\n'); }
if (!txt) { txt = (first.output ?? first.text ?? JSON.stringify(first)).toString(); }
txt = txt.slice(0, 4400);
const s = $getWorkflowStaticData('global');
if (/^【改程式】/.test(txt)) {
  const DIR = 'C:\\Users\\ryan\\Desktop\\opencode';
  const bad = [/rm\s+-rf\s+[\/~.]/i, /remove-item\b.*(-recurse|\/s)/i, /\bdel\s+\/[sfq]/i, /\bformat\s+[a-z]:/i, /\b(rd|rmdir)\s+\/s/i, /\.env/i, /NGROK_AUTHTOKEN/i, /CHANNEL_ACCESS_TOKEN/i, /OPENCODE_SERVER_PASSWORD/i, /\.git[\/\\]/i, /\bgit\s+push\b/i, /\bgit\s+reset\s+--hard\b/i, /\bnpm\s+publish\b/i, /\b(shutdown|taskkill|stop-process|stop-computer)\b/i, /\breg\s+delete\b/i, /\b(ssh|scp|plink)\b/i, /\|\s*(ba|z)?sh\b/i, /\b(invoke-webrequest|invoke-restmethod|iwr|curl)\b/i, /base64\s+-d/i];
  const hit = bad.find(r => r.test(orig));
  if (hit) { delete s.pending; return [{ json: { userId: uid, output: '已擋下高風險字 (' + hit + ')，請換說法或本機處理。' } }]; }
  s.pending = { userId: uid, prompt: orig, directory: DIR, createdAt: Date.now() };
  return [{ json: { userId: uid, output: `${txt}\n\n回 好 執行（5分鐘內），取消 取消` } }];
}
delete s.pending;
txt = txt.replace(/^【問答】\s*/, '');
return [{ json: { userId: uid, output: txt.slice(0, 4800) || '收到' } }];

const j = $input.first().json;
let uid = '';
try { uid = $('Parse LINE').first().json.userId ?? ''; } catch(e) {}
let msg = '';
if (j && j.error) { msg = j.error.message || j.error.description || JSON.stringify(j.error); }
else { msg = j.message || JSON.stringify(j); }
msg = String(msg).slice(0, 1000);
return [{ json: { userId: uid, output: `執行失敗:\n${msg}\n\n請確認桌機已啟動 opencode serve（0.0.0.0:4096）後再試。` } }];

const j = $input.first().json;
const text = (j.prompt ?? j.text ?? '').trim();
const s = $getWorkflowStaticData('global');
if (/取消|不要了|算了|不用了|別做|停止|cancel/i.test(text)) { delete s.pending; return [{ json: { userId: j.userId, output: '已取消，不會執行。直接傳新訊息即可。' } }]; }
if (s.pending) { delete s.pending; return [{ json: { userId: j.userId, output: '已取消待確認事項。直接傳新訊息即可。' } }]; }
return [{ json: { userId: j.userId, output: '直接傳訊息即可，不用指令。\n問答會直接回，改程式會先給預覽，你回 好 才執行，取消 就取消。' } }];
